namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A traditional Neapolitan pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps =
            [
                "Preheat oven to 475°F (245°C) with a pizza stone.",
                "Stretch dough into a 12-inch round.",
                "Spread crushed tomatoes over the dough.",
                "Tear mozzarella into pieces and distribute evenly.",
                "Bake for 10–12 minutes until crust is golden.",
                "Top with fresh basil and a drizzle of olive oil."
            ],
            TotalRatings = 12, RatingSum = 53
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps =
            [
                "Cook spaghetti in salted boiling water until al dente.",
                "Crisp pancetta in a skillet over medium heat.",
                "Whisk eggs with grated Pecorino and black pepper.",
                "Toss hot pasta with pancetta, then remove from heat.",
                "Quickly stir in egg mixture, tossing to create a creamy sauce.",
                "Serve immediately with extra cheese and pepper."
            ],
            TotalRatings = 8, RatingSum = 38
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps =
            [
                "Marinate chicken in yogurt and spices for at least 1 hour.",
                "Grill or broil chicken until charred.",
                "Sauté onion, garlic, and ginger until fragrant.",
                "Add tomato sauce and spices, simmer for 15 minutes.",
                "Stir in cream and add grilled chicken pieces.",
                "Simmer for 10 minutes and serve with basmati rice."
            ],
            TotalRatings = 15, RatingSum = 70
        },
        new()
        {
            Id = 4, Title = "Vegetable Biryani", Category = "Indian",
            Description = "Fragrant layered rice dish with mixed vegetables and aromatic spices.",
            Ingredients = ["Basmati rice", "Mixed vegetables", "Onions", "Saffron", "Whole spices", "Ghee", "Mint", "Cilantro"],
            Steps =
            [
                "Soak basmati rice for 30 minutes, then parboil.",
                "Fry sliced onions until golden brown.",
                "Cook vegetables with spices until tender.",
                "Layer rice and vegetable mixture in a heavy pot.",
                "Add saffron milk, fried onions, and fresh herbs.",
                "Seal and cook on low heat for 25 minutes."
            ],
            TotalRatings = 6, RatingSum = 27
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in corn tortillas with fresh toppings.",
            Ingredients = ["Ground beef", "Corn tortillas", "Lettuce", "Tomato", "Cheese", "Sour cream", "Taco seasoning"],
            Steps =
            [
                "Brown ground beef in a skillet over medium-high heat.",
                "Add taco seasoning and water, simmer until thickened.",
                "Warm corn tortillas in a dry skillet.",
                "Fill tortillas with seasoned beef.",
                "Top with shredded lettuce, diced tomato, cheese, and sour cream.",
                "Serve with lime wedges and salsa."
            ],
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh avocado dip with lime, cilantro, and jalapeño.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps =
            [
                "Halve and pit ripe avocados, scoop into a bowl.",
                "Mash with a fork to desired consistency.",
                "Stir in diced onion, jalapeño, and tomato.",
                "Add lime juice, chopped cilantro, and salt.",
                "Taste and adjust seasoning.",
                "Serve immediately with tortilla chips."
            ],
            TotalRatings = 9, RatingSum = 41
        },
        new()
        {
            Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual chocolate cakes with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps =
            [
                "Preheat oven to 425°F (220°C). Butter and flour ramekins.",
                "Melt chocolate and butter together, let cool slightly.",
                "Whisk eggs, egg yolks, and sugar until thick.",
                "Fold chocolate mixture into eggs, then fold in flour.",
                "Pour into ramekins and bake for 12–14 minutes.",
                "Invert onto plates and serve immediately."
            ],
            TotalRatings = 18, RatingSum = 86
        },
        new()
        {
            Id = 8, Title = "Tiramisu", Category = "Desserts",
            Description = "Classic Italian layered dessert with coffee-soaked ladyfingers and mascarpone cream.",
            Ingredients = ["Ladyfingers", "Mascarpone", "Eggs", "Sugar", "Espresso", "Cocoa powder", "Marsala wine"],
            Steps =
            [
                "Brew espresso and let cool. Mix with Marsala wine.",
                "Separate eggs. Beat yolks with sugar until pale.",
                "Fold mascarpone into yolk mixture until smooth.",
                "Whip egg whites to stiff peaks and fold into mascarpone mixture.",
                "Dip ladyfingers briefly in espresso and layer in a dish.",
                "Spread mascarpone cream over ladyfingers. Repeat layers.",
                "Refrigerate for at least 4 hours. Dust with cocoa before serving."
            ],
            TotalRatings = 14, RatingSum = 65
        }
    ];

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public Dictionary<string, int> GetCategoryCounts() =>
        _recipes.GroupBy(r => r.Category).ToDictionary(g => g.Key, g => g.Count());

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title.Trim(),
            Category = submission.Category.Trim(),
            Description = $"A community-submitted {submission.Category.ToLower()} recipe.",
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

