@page "/"
@using RecipeHub.Services

<PageTitle>RecipeHub — Home</PageTitle>

<div class="hero">
    <h1>🍳 Welcome to RecipeHub</h1>
    <p class="lead">Discover, share, and rate recipes from our community of home cooks.</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var cat in categoryCounts)
    {
        <a class="category-card" href="category/@Uri.EscapeDataString(cat.Key)">
            <span class="category-icon">@GetCategoryIcon(cat.Key)</span>
            <h3>@cat.Key</h3>
            <p>@cat.Value recipe@(cat.Value != 1 ? "s" : "")</p>
        </a>
    }
</div>

<div class="cta-section">
    <h2>Have a recipe to share?</h2>
    <p>Join our community and submit your favorite recipes for others to enjoy.</p>
    <a class="btn-submit" href="submit">Submit a Recipe</a>
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Dictionary<string, int> categoryCounts = new();

    protected override void OnInitialized()
    {
        categoryCounts = RecipeService.GetCategoryCounts();
    }

    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

