@page "/category/{CategoryName}"
@using RecipeHub.Services
@using RecipeHub.Models

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <a href="/">← Back to Categories</a>
</nav>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <a class="recipe-card" href="recipe/@recipe.Id">
                <h3>@recipe.Title</h3>
                <p>@recipe.Description</p>
                <div class="recipe-meta">
                    <span class="rating">★ @recipe.AverageRating.ToString("F1")</span>
                    <span class="count">@recipe.TotalRatings ratings</span>
                    <span class="ingredients">@recipe.Ingredients.Count ingredients</span>
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/category/{CategoryName}"

.recipe-list {
    display: grid;
    gap: 1rem;
}

.recipe-card {
    display: block;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s, border-color 0.2s;
}

.recipe-card:hover {
    border-color: #4a90d9;
    box-shadow: 0 2px 8px rgba(74, 144, 217, 0.15);
}

.recipe-card h3 {
    margin: 0 0 0.5rem;
    color: #333;
}

.recipe-card p {
    margin: 0 0 0.75rem;
    color: #666;
}

.recipe-meta {
    display: flex;
    gap: 1rem;
    font-size: 0.85rem;
    color: #888;
}

.recipe-meta .rating {
    color: #e0a800;
    font-weight: 600;
}

nav[aria-label="breadcrumb"] {
    margin-bottom: 1rem;
}

nav[aria-label="breadcrumb"] a {
    color: #4a90d9;
    text-decoration: none;
}

nav[aria-label="breadcrumb"] a:hover {
    text-decoration: underline;
}

@page "/recipe/{RecipeId:int}"
@using RecipeHub.Services
@using RecipeHub.Models

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <nav aria-label="breadcrumb">
        <a href="/">Home</a> &rsaquo;
        <a href="category/@Uri.EscapeDataString(recipe.Category)">@recipe.Category</a> &rsaquo;
        <span>@recipe.Title</span>
    </nav>

    <h1>@recipe.Title</h1>
    <p class="recipe-description">@recipe.Description</p>

    <StarRating RecipeId="recipe.Id"
                AverageRating="recipe.AverageRating"
                TotalRatings="recipe.TotalRatings" />

    <section class="recipe-section">
        <h2>🥘 Ingredients</h2>
        <ul class="ingredients-list">
            @foreach (var ingredient in recipe.Ingredients)
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>📝 Steps</h2>
        <ol class="steps-list">
            @foreach (var step in recipe.Steps)
            {
                <li>@step</li>
            }
        </ol>
    </section>
}

