@page "/submit"
@rendermode InteractiveServer
@using System.ComponentModel.DataAnnotations
@using RecipeHub.Services
@using RecipeHub.Models

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>📝 Submit a Recipe</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>🎉 Recipe Submitted!</h2>
        <p>Your recipe "<strong>@Submission!.Title</strong>" has been added to the @Submission.Category category.</p>
        <a href="recipe/@submittedId">View your recipe →</a>
    </div>
}
else
{
    <p>Share your favorite recipe with the community.</p>

    <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="Submission!.Title" placeholder="e.g. Grandma's Apple Pie" />
            <ValidationMessage For="() => Submission!.Title" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="Submission!.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in categories)
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Submission!.Category" />
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="Submission!.Ingredients" rows="6"
                           placeholder="2 cups flour&#10;1 cup sugar&#10;3 large eggs" />
            <ValidationMessage For="() => Submission!.Ingredients" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Submission!.Steps" rows="6"
                           placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
            <ValidationMessage For="() => Submission!.Steps" />
        </div>

        <button type="submit" disabled="@isSubmitting">
            @(isSubmitting ? "Submitting..." : "Submit Recipe")
        </button>
    </EditForm>
}

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private SubmissionModel? Submission { get; set; }
    private IReadOnlyList<string> categories = [];
    private bool submitted;
    private bool isSubmitting;
    private int submittedId;

    protected override void OnInitialized()
    {
        Submission ??= new();
        categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        isSubmitting = true;
        try
        {
            var recipe = RecipeService.AddRecipe(new RecipeSubmission
            {
                Title = Submission!.Title!,
                Category = Submission.Category!,
                Ingredients = Submission.Ingredients!,
                Steps = Submission.Steps!
            });
            submittedId = recipe.Id;
            submitted = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private class SubmissionModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be 3–100 characters.")]
        public string? Title { get; set; }

        [Required(ErrorMessage = "Please select a category.")]
        public string? Category { get; set; }

        [Required(ErrorMessage = "Please list at least one ingredient.")]
        public string? Ingredients { get; set; }

        [Required(ErrorMessage = "Please describe the steps.")]
        public string? Steps { get; set; }
    }
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
    color: #333;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    max-width: 500px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 1rem;
    font-family: inherit;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4a90d9;
    box-shadow: 0 0 0 2px rgba(74, 144, 217, 0.2);
}

.form-group .invalid {
    border-color: #dc3545;
}

button[type="submit"] {
    padding: 0.6rem 1.5rem;
    background: #4a90d9;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.2s;
}

button[type="submit"]:hover:not(:disabled) {
    background: #357abd;
}

button[type="submit"]:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.success-message {
    padding: 1.5rem;
    background: #d4edda;
    border: 1px solid #c3e6cb;
    border-radius: 8px;
    margin-top: 1rem;
}

.success-message h2 {
    margin-top: 0;
    color: #155724;
}

.success-message a {
    color: #155724;
